0] WRAP_PROCESS_WORD = 3'd3;\n    localparam [2:0] CALC_SCROLL = 3'd4;\n    localparam [2:0] RENDER = 3'd5;\n    localparam [2:0] FINISH = 3'd6;\n\n    reg [2:0] state, next_state;\n\n    // --- Internal Registers ---\n    // RAM storage (32 lines x 80 bits)\n    reg [79:0] ram_text [0:31];\n    \n    // Wrapped text buffer (64 lines x 20 chars x 8 bits)\n    // Flattened: 64 entries of 160 bits, or 2D unpacked.\n    // Icarus Verilog supports unpacked arrays.\n    reg [7:0] wrapped_text [0:63][0:19];\n    \n    // Processing Registers\n    reg [5:0] wrapped_lines_count; // L\n    reg [5:0] current_wrap_idx;\n    \n    // Current line being constructed (packed LSB first: char 0 at [7:0])\n    reg [159:0] current_line_packed;\n    reg [3:0] current_line_len;\n    \n    // Parsing Registers\n    reg [4:0] parse_line_idx;\n    reg [3:0] parse_char_idx; // 0-9 (for 10 chars per line)\n    reg [159:0] word_buf_packed;\n    reg [3:0] word_buf_len;\n    reg parsing_word;\n    \n    // Pending Word Registers (for WRAP_PROCESS_WORD)\n    reg [159:0] pending_word;\n    reg [3:0] pending_len;\n    reg pending_line_end;\n    \n    // Rendering Registers\n    reg [5:0] render_line_idx;\n    reg [3:0] render_char_idx;\n    reg [3:0] output_counter;\n    reg [2:0] thumb_pos;\n    reg [4:0] cycle_count;\n\n    // --- Combinational Logic ---\n    wire [4:0] track_height;\n    wire [5:0] scroll_limit;\n    \n    assign track_height = (H > 3) ? (H - 3) : 0;\n    assign scroll_limit = (wrapped_lines_count > H) ? (wrapped_lines_count - H) : 0;\n\n    // --- Main FSM ---\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            output_valid <= 1'b0;\n            done <= 1'b0;\n            output_char <= 8'd0;\n            wrapped_lines_count <= 6'd0;\n            cycle_count <= 5'd0;\n            // Reset RAM content (optional, but good for simulation)\n            // In hardware, RAM is undefined on power up, but we rely on inp